#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" others sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  # Held in memory, so no temp file with secrets is left behind on Ctrl-C.
  others=$(grep -vE "^${key}=" "$ENV_FILE" || true)
  { [[ -z "$others" ]] || printf '%s\n' "$others"; printf "%s='%s'\n" "$key" "${value//\'/$sq}"; } > "$ENV_FILE"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the steps only the owner can do. docs/operations.md explains each one.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Every value is kept in a private file outside the repo, so a re-run reuses what it saved (secrets included).
if [[ "$ENV_FILE" == ".env" ]]; then
  ENV_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/devbrief/production.env"
fi
(umask 077 && mkdir -p "$(dirname "$ENV_FILE")")
chmod 600 "$ENV_FILE" 2>/dev/null || true

banner "DevBrief production setup"

stage "Domain"
say "DevBrief needs one domain; the web app and the API share it."
step "Buy or pick a domain at any registrar (PRD O2: not chosen yet)."
DOMAIN=$(_existing APP_URL || true); DOMAIN=${DOMAIN#https://}
[[ -n "$DOMAIN" ]] && write_env DOMAIN "$DOMAIN"
ask DOMAIN "Domain, without https:// (for example devbrief.example):"
DOMAIN=${DOMAIN#http*://}; DOMAIN=${DOMAIN%/}
write_env DOMAIN "$DOMAIN"
write_env APP_URL "https://${DOMAIN}"
write_env API_INTERNAL_URL "https://${DOMAIN}"

stage "Hetzner VPS"
open_url "https://console.hetzner.cloud/"
step "Create a project, then Add Server: Ubuntu 24.04, a shared-vCPU plan with at least 4 GB RAM."
step "Add your SSH public key, then create the server."
ask SERVER_IP "Paste the server's public IPv4 address:"
write_env SERVER_IP "$SERVER_IP"
step "At your registrar, add an A record: ${DOMAIN} -> ${SERVER_IP} (and AAAA for IPv6 if you like)."
pause "DNS added? Press Enter."

stage "Coolify"
say "Install Coolify on the server (the official script, run as root):"
step "ssh root@${SERVER_IP}"
step "curl -fsSL https://cdn.coollabs.io/coolify/install.sh | bash"
open_url "http://${SERVER_IP}:8000"
step "Create the admin account right away, then finish the onboarding (localhost server)."
step "Settings -> Configuration: set the instance domain to a subdomain like coolify.${DOMAIN} if you want HTTPS for the dashboard."
pause "Coolify is up and you can log in? Press Enter."

stage "Sentry"
open_url "https://sentry.io/organizations/new/"
step "Create two projects: devbrief-api (platform Node.js / NestJS) and devbrief-web (platform Next.js)."
step "For each: Settings -> Client Keys (DSN) -> copy the DSN."
ask SENTRY_DSN "Paste the devbrief-api DSN:"
write_env SENTRY_DSN "$SENTRY_DSN"
ask NEXT_PUBLIC_SENTRY_DSN "Paste the devbrief-web DSN:"
write_env NEXT_PUBLIC_SENTRY_DSN "$NEXT_PUBLIC_SENTRY_DSN"
open_url "https://sentry.io/settings/auth-tokens/"
step "Create an Organization Token; it uploads source maps at build time."
ask_secret SENTRY_AUTH_TOKEN "Paste the auth token:"
write_env SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
ask SENTRY_ORG "Organization slug (in the Sentry URL):"
write_env SENTRY_ORG "$SENTRY_ORG"
write_env SENTRY_PROJECT "devbrief-web"

stage "Backup bucket (S3-compatible)"
open_url "https://console.hetzner.cloud/"
step "Object Storage -> Create bucket (private), for example devbrief-backups. Note its region endpoint."
step "Security -> S3 credentials -> Generate credentials; copy both values."
ask S3_ENDPOINT "Endpoint URL (for example https://fsn1.your-objectstorage.com):"
write_env S3_ENDPOINT "$S3_ENDPOINT"
ask S3_BUCKET "Bucket name:"
write_env S3_BUCKET "$S3_BUCKET"
ask S3_ACCESS_KEY "Access key:"
write_env S3_ACCESS_KEY "$S3_ACCESS_KEY"
ask_secret S3_SECRET_KEY "Secret key:"
write_env S3_SECRET_KEY "$S3_SECRET_KEY"
note "These go into Coolify (Storages), not into the app's environment."

stage "GitHub OAuth app"
open_url "https://github.com/settings/applications/new"
step "Application name: DevBrief. Homepage URL: ${APP_URL}"
step "Authorization callback URL: ${APP_URL}/api/auth/callback/github"
step "Register, then Generate a new client secret."
ask GITHUB_CLIENT_ID "Client ID:"
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
ask_secret GITHUB_CLIENT_SECRET "Client secret:"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"

stage "Google OAuth client"
open_url "https://console.cloud.google.com/apis/credentials"
step "OAuth consent screen: external app, scopes openid, email, profile (publish it to production)."
step "Create credentials -> OAuth client ID -> Web application."
step "Authorized JavaScript origin: ${APP_URL}"
step "Authorized redirect URI: ${APP_URL}/api/auth/callback/google"
ask GOOGLE_CLIENT_ID "Client ID:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
ask_secret GOOGLE_CLIENT_SECRET "Client secret:"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

stage "Generated secrets"
say "Random values for the app; nothing to copy from a website."
# ensure_secret KEY GENERATOR: keeps a saved value unless the human agrees to rotate it.
ensure_secret() {
  local key="$1" generator="$2"
  if [[ -n "$(_existing "$key" || true)" ]]; then
    warn "$key already exists. Rotating it signs every user out or breaks web-to-api calls until Coolify has the new value."
    confirm "Rotate $key?" || return 0
  fi
  write_env "$key" "$(eval "$generator")"
}
if command -v openssl >/dev/null 2>&1; then
  ensure_secret BETTER_AUTH_SECRET "openssl rand -base64 32"
  ensure_secret INTERNAL_API_TOKEN "openssl rand -hex 24"
else
  warn "openssl not found; generate BETTER_AUTH_SECRET and INTERNAL_API_TOKEN yourself"
fi
write_env AUTH_TEST_MODE "false"
write_env INGEST_ON_BOOT "true"

# The Coolify file holds only application variables; the provider values stay in ENV_FILE.
COOLIFY_FILE="${ENV_FILE%.env}.coolify.env"
(umask 077 && grep -vE '^(DOMAIN|SERVER_IP|S3_[A-Z_]+)=' "$ENV_FILE" > "$COOLIFY_FILE")
say ""
say "Next: open docs/operations.md, 'First-time setup', and enter the values from ${COOLIFY_FILE} in Coolify."
say "That file and ${ENV_FILE} sit outside the repo (mode 600); keep ${ENV_FILE} so a re-run reuses the secrets. Delete ${COOLIFY_FILE} once Coolify has the values."

finish
}

run_wizard "$@"; exit
